#!/usr/bin/env python3
"""Kaggle script kernel generated by scripts/kg.py. Script kernels upload one file, so the code comes from the
attached private dataset: find it under /kaggle/input and run the configured module. Both T4s stay visible: a module
that wants them starts one process per GPU."""
import json
import os
import shutil
import subprocess
import sys

CONFIG = json.loads(r"""__CONFIG__""")

if CONFIG["pip"]:
    subprocess.run([sys.executable, "-m", "pip", "install", "-q", "-U", *CONFIG["pip"]], check=True)
# The image's torchao is too old for current peft, which refuses to run with it. Nothing here uses it.
subprocess.run([sys.executable, "-m", "pip", "uninstall", "-q", "-y", "torchao"], check=False)


def find_code():
    """Kaggle flattens a dataset holding one zipped folder, so match on contents and rebuild the package name."""
    for d, dirs, files in os.walk("/kaggle/input"):
        dirs[:] = [x for x in dirs if x != "audio" and not x.endswith("_environment")]
        if {"__init__.py", "infer.py", "train.py", "scorer.py"} <= set(files):
            os.makedirs("/tmp/code", exist_ok=True)
            os.symlink(d, "/tmp/code/lifemate")
            return "/tmp/code"
    raise SystemExit("lifemate code not found under /kaggle/input")


env = {**os.environ, "PYTHONPATH": find_code(), "TOKENIZERS_PARALLELISM": "false",
       "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True", "MALLOC_ARENA_MAX": "2"}
os.environ.update(env)
if shutil.which("nvidia-smi"):  # absent on CPU kernels
    subprocess.run(["nvidia-smi", "-L"])
stamp = os.path.join(env["PYTHONPATH"], "lifemate", "BUILD.txt")
print("code build:", open(stamp, encoding="utf-8").read().strip() if os.path.exists(stamp) else "unknown", flush=True)
sys.exit(subprocess.run([sys.executable, "-m", CONFIG["module"], *CONFIG["args"]], env=env).returncode)
